  ui_story_31150401_26_option_content = "Terima kasih telah menghadirkan nuansa alam di Colossus.",
  ui_story_31150401_27_dialog_content = "Ah, tak perlu berterima kasih begitu. Ini biasa saja, kok.",
  ui_story_31150401_28_dialog_content = "Aku senang sekali kau ada di sini, Naroxel. Mungkin kelak kita bisa mengubah Colossus menjadi tempat yang seperti Eraveil...",
  ui_story_31150401_29_option_content = "Benarkah semenakjubkan itu?",
  ui_story_31150401_30_dialog_content = "Kau belum pernah melihat tempat yang sama saat menjelajah di luar Colossus?",
  ui_story_31150401_31_dialog_content = "Kau pasti memperhatikan perbedaan antara kota yang kering dan menyesakkan dengan hutan yang lembap dan menyegarkan, 'kan?",
  ui_story_31150401_32_dialog_content = "Benar. Aku malu mengakuinya, tapi meskipun aku ini Caelestite, pemahamanku atas alam...",
  ui_story_31150401_33_dialog_content = "Ah!",
  ui_story_31150401_34_dialog_content = "Hati-hati! Maaf, aku lupa memberitahumu bahwa ada beberapa kaktus di sini.",
