  ui_story_31150401_48_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian.</color>",
  ui_story_31150401_49_dialog_content = "Hmm... Sepertinya berasal dari kamar Navigator.",
  ui_story_31150401_50_dialog_content = "<color=#e8d9bb>Tok, tok.</color>",
  ui_story_31150401_51_dialog_content = "Naroxel... Ada apa?",
  ui_story_31150401_52_dialog_content = "Sepertinya ada... sinyal minta bantuan dari kamarmu.",
