  ui_story_31150401_54_dialog_content = "Hah? Sinyal minta bantuan? Tapi, aku baik-baik saja, kok. Aku belum mengirim sinyal apa pun...",
  ui_story_31150401_55_dialog_content = "Kalau kau tidak keberatan, bolehkah aku masuk dan memeriksanya?",
  ui_story_31150401_56_option_content = "Tentu saja.",
  ui_story_31150401_57_dialog_content = "Terima kasih banyak. Akan kuperiksa sekarang...",
  ui_story_31150401_58_option_content = "Eh...",
  ui_story_31150401_59_dialog_content = "Jangan khawatir. Aku hanya ingin mengonfirmasi sumber sinyal itu.",
