  ui_story_31150401_77_dialog_content = "Tanaman juga menua, layu, dan mati—serta merespons stimulus eksternal.",
  ui_story_31150401_78_dialog_content = "Tanaman punya cara untuk mengekspresikan diri.",
  ui_story_31150401_79_dialog_content = "Karena sedikit lebih peka terhadap tanaman ketimbang kebanyakan orang, aku bisa mendeteksi feromon yang dikeluarkan tumbuhan.",
  ui_story_31150401_80_dialog_content = "Sedikit lebih peka...?",
  ui_story_31150401_81_dialog_content = "Tadinya kupikir kau juga bisa merasakan sinyal ini—tentu saja dengan kemampuan psikis Caelestite-mu itu.",
  ui_story_31150401_82_dialog_content = "Aku belum begitu mahir menggunakan kemampuanku pada tanaman...",
  ui_story_31150401_83_dialog_content = "Jangan khawatir. Meski tak bisa merasakan pikirannya, kau bisa memahami kebutuhannya kalau mengamatinya dengan cukup cermat.",
  ui_story_31150401_84_dialog_content = "Misalnya saja kaktus ini. Seperti yang kamu tahu, tanaman ini berasal dari gurun.",
  ui_story_31150401_85_dialog_content = "Apa yang kamu rasakan saat pergi ke gurun?",
  ui_story_31150401_86_option_content = "Aku merasa... haus?",
  ui_story_31150401_87_dialog_content = "Benar. Nah, begitu juga dengan tanaman.",
  ui_story_31150401_88_option_content = "Aku merasa lelah.",
  ui_story_31150401_89_dialog_content = "Karena cuaca yang panas dan kelangkaan air, tinggal di gurun itu sangat sulit.",
  ui_story_31150401_90_dialog_content = "Nah, kaktus berhasil beradaptasi dengan kehidupan gurun.",
  ui_story_31150401_91_dialog_content = "Kaktus menumbuhkan duri-duri kecil yang tajam untuk mengurangi kadar air yang hilang.",
  ui_story_31150401_92_dialog_content = "Batangnya yang kuat dan kokoh berfungsi untuk menyimpan lebih banyak air.",
  ui_story_31150401_93_dialog_content = "Dengan begitu, bisa dibilang bahwa kaktus telah beradaptasi secara sempurna dengan lingkungannya.",
  ui_story_31150401_94_dialog_content = "Beradaptasi secara sempurna dengan lingkungannya....",
  ui_story_31150401_95_dialog_content = "Jadi, maksudmu, kaktus tidak butuh terlalu banyak air?",
  ui_story_31150401_96_dialog_content = "Iya. Sangat tangguh, 'kan?",
  ui_story_31150401_97_dialog_content = "Tadinya kukira memberinya banyak air dan pupuk adalah cara terbaik untuk merawatnya...",
  ui_story_31150401_98_dialog_content = "Aku menyiraminya setiap pagi dan sore hari... Tapi, sepertinya aku justru merugikannya...",
  ui_story_31150401_99_dialog_content = "Yah, kadang kalau tidak memahami kebutuhan orang-orang di sekitarmu, ada kemungkinan kamu secara tak sengaja justru menyebabkan lebih banyak kerugian daripada kebaikan...",
  ui_story_31150401_100_dialog_content = "Ini bukan masalah serius, kok. Jangan terlalu menyalahkan diri, ya...",
  ui_story_31150401_101_dialog_content = "Bisakah kamu tunjukkan cara merawat yang tepat, Naroxel?",
  ui_story_31150401_102_dialog_content = "Aku janji akan merawatnya dengan baik kali ini!",
  ui_story_31150401_103_dialog_content = "Tentu saja. Rasanya terharu juga melihat tekadmu.",
  ui_story_31150401_104_dialog_content = "Alam akan menunjukkan caranya padamu.",
  ui_story_31150401_105_dialog_content = "Mungkin sudah saatnya aku memberikannya padamu...",
  ui_story_31150401_106_dialog_content = "Hah? Apa maksudmu?",
  ui_story_31150401_107_dialog_content = "Eh, jangan hiraukan. Aku hanya bicara pada diri sendiri.",
  ui_story_31150401_108_dialog_content = "Nah, sekarang akan kuberi tahu cara merawat kaktus ini, ya.",
  ui_story_31150401_109_dialog_content = "Aku siap mendengar!",
  ui_story_31150401_110_dialog_content = "Navigator, aku datang lagi untuk mengganggumu.",
  ui_story_31150401_111_dialog_content = "Naroxel, kau tidak kemari untuk memeriksa apakah aku merawat kaktusnya dengan baik, 'kan?",
  ui_story_31150401_112_dialog_content = "Yah, karena kamu bilang begitu... tak ada salahnya kalau kulihat, 'kan?",
  ui_story_31150401_113_dialog_content = "Tapi, hanya berdiri di pintu sini saja aku bisa merasakan bahwa kaktus itu sudah pulih.",
  ui_story_31150401_114_dialog_content = "Benarkah? Aku terus-terusan merasa cemas. Aku takut kalau aku sampai menyakitinya lagi...",
  ui_story_31150401_115_dialog_content = "Yah, aku senang tidak ada bagian yang layu atau busuk, kok.",
  ui_story_31150401_116_dialog_content = "Jadi... Feromon macam apa yang dikeluarkannya sekarang?",
  ui_story_31150401_117_dialog_content = "Kamu benar-benar ingin tahu, Navigator?",
  ui_story_31150401_118_dialog_content = "Sepertinya begitu... Entahlah, tapi akhir-akhir ini kaktus itu membuatku teringat pada Rediesel Wrench...",
  ui_story_31150401_119_dialog_content = "Aku khawatir kaktus dari gurun itu sama pemarahnya dengan mereka...",
  ui_story_31150401_120_dialog_content = "Kecemasanmu itu tidak beralasan. Lagi pula, lingkungan berperan besar bagi pertumbuhan.",
  ui_story_31150401_121_dialog_content = "Saat ini, kaktus itu... mengeluh karena kamu hampir membunuhnya.",
  ui_story_31150401_122_dialog_content = "...!",
  ui_story_31150401_123_dialog_content = "Haha, aku hanya bercanda, kok.",
  ui_story_31150401_124_dialog_content = "Jangan khawatir, Navigator. Aku bisa merasakan tanaman itu melepaskan feromon yang menyenangkan.",
  ui_story_31150401_125_dialog_content = "Tak kusangka kau bakal mengerjaiku...",
  ui_story_31150401_126_dialog_content = "Kau pasti juga tidak menyangka yang satu ini.",
  ui_story_31150401_127_dialog_content = "Ini... tanaman baru—untukku?",
  ui_story_31150401_128_dialog_content = "Akan kuberikan padamu kalau kamu bisa menjelaskan dengan benar cara merawat tanaman ini.",
  ui_story_31150401_129_dialog_content = "Bukan masalah!",
  ui_story_31150401_130_dialog_content = "Hmm... Dari tampilannya, ini jenis tanaman yang perlu disiram secara rutin, 'kan?",
  ui_story_31150401_131_dialog_content = "Karena daunnya sangat berbeda dengan kaktus... Sepertinya... tanahnya harus selalu lembap.",
  ui_story_31150401_132_dialog_content = "Nah, sekarang kelihatannya tanaman ini... sedang dalam fase berbunga. Disebut begitu, 'kan? Jadi, mungkin aku perlu memupuknya...",
  ui_story_31150401_133_dialog_content = "Pada dasarnya, sepertinya aku harus bereksperimen sedikit untuk memastikannya.",
  ui_story_31150401_134_dialog_content = "Yah, aku yakin kau sudah memahami kebutuhan tanaman ini hanya dengan mengamatinya saja.",
  ui_story_31150401_135_dialog_content = "Ambillah. Semoga kamu mendapatkan sesuatu yang benar-benar berharga bagimu dari tanaman ini.",
  ui_story_31150401_136_dialog_content = "Terima kasih. Aku akan menjaganya dengan baik!",
  ui_story_31150401_137_dialog_content = "Tapi... Bunga macam apa ini?",
  ui_story_31150401_138_dialog_content = "Rupanya Naroxel sudah pergi...",
  ui_story_31150401_139_dialog_content = "Jangan cemas! Meski tidak tahu namamu, aku akan memberimu lingkungan yang menyenangkan!",
  ui_story_31150401_140_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian.</color>",
  ui_story_31150401_141_dialog_content = "Aneh... Tiba-tiba aku bisa merasakan... kegembiraan di sekitar.",
  ui_story_31150401_142_dialog_content = "Omong-omong... Seberapa banyak air yang ingin kamu minum hari ini, teman kecil?",
  ui_story_31150401_143_dialog_content = "Hah...? Bulu-bulu putih apa ini?",
  ui_story_31150401_144_dialog_content = "Wah, ini bunga dandelion!",
  ui_story_31150401_145_dialog_content = "Aku pernah melihatnya di suatu kilasan dari masa lalu. Dulu tanaman yang seperti ini tumbuh di Eraveil...",
  ui_story_31150401_146_dialog_content = "Semoga kamu mendapatkan sesuatu yang benar-benar berharga bagimu.",
  ui_story_31150401_147_dialog_content = "Naroxel...",
  ui_story_31150401_148_dialog_content = "Terima kasih.",
  ui_story_31150601_1_dialog_content = "Aroma angin laut yang asin...",
  ui_story_31150601_2_dialog_content = "Dan sinar matahari hari ini sangat bagus.",
  ui_story_31150601_3_dialog_content = "Rasanya sudah sangat lama sejak terakhir kali saya pergi berlibur dari semua kekhawatiran saya...",
  ui_story_31150601_4_dialog_content = "Naroxel?",
  ui_story_31150601_5_dialog_content = "PlayerName?",
  ui_story_31150601_6_dialog_content = "Tidak menyangka melihat kamu di sini.",
  ui_story_31150601_7_dialog_content = "Apakah saya mengganggu liburan Anda?",
  ui_story_31150601_8_dialog_content = "Tentu saja tidak, saya hanya terkejut melihatmu.",
  ui_story_31150601_9_dialog_content = "Saya baru saja meratapi kenyataan bahwa tidak ada siapa-siapa untuk diajak bicara.",
  ui_story_31150601_10_dialog_content = "Baru saja saya melihat Bessie dari sisi jalan yang lain.",
  ui_story_31150601_11_dialog_content = "Tanduk dan tubuhnya benar-benar menarik perhatian—",
  ui_story_31150601_12_dialog_content = "Saya tidak akan datang dan menemukan kamu jika saya tidak melihatnya.",
  ui_story_31150601_13_dialog_content = "Oh, jadi begitu kamu menemukanku.",
  ui_story_31150601_14_dialog_content = "Angin laut di sekitar sini benar-benar luhur.",
  ui_story_31150601_15_dialog_content = "Maukah kamu ke sini dan beristirahat sejenak?",
  ui_story_31150601_16_dialog_content = "Aku akan duduk di kursi kosong ini di sampingmu.",
  ui_story_31150601_17_dialog_content = "Mengapa kamu tiba-tiba memutuskan untuk pergi berlibur?",
  ui_story_31150601_18_dialog_content = "Heheh, tidak bisa memahami ide seorang workaholic yang tiba-tiba memilih untuk beristirahat?",
  ui_story_31150601_19_dialog_content = "Untuk memenuhi kebutuhan pengantaran di Lumopolis, Courier Union baru-baru ini memperkenalkan beberapa freelancer baru.",
  ui_story_31150601_20_dialog_content = "Saya telah banyak bekerja keras untuk melatih mereka.",
  ui_story_31150601_21_dialog_content = "Dan suatu hari, Wendy menemukan saya benar-benar kelelahan dan roboh di depan pintu masuk serikat.",
  ui_story_31150601_22_dialog_content = "Jadi, Wendy sangat menyarankan agar saya pergi berlibur, dan jadi—",
  ui_story_31150601_23_dialog_content = "Seperti yang kamu lihat, saya memutuskan untuk pergi ke tepi pantai untuk bersantai sejenak.",
  ui_story_31150601_24_dialog_content = "Cara kamu selalu bekerja keras itu. Rasanya membuatku merasa malu pada diri sendiri.",
  ui_story_31150601_25_dialog_content = "Apakah kamu mencoba memuji aku?",
  ui_story_31150601_26_dialog_content = "Dalam pandangan para pemula itu, saya hanyalah fosil kuno yang keras kepala dalam mengikuti aturan...",
  ui_story_31150601_27_dialog_content = "Apa yang terjadi?",
  ui_story_31150601_28_dialog_content = "Kamu adalah anggota senior dari Courier Union. Aku tidak pernah menyangka pemula akan berani begitu kurang ajar.",
  ui_story_31150601_29_dialog_content = "Tolong jangan terlalu keras menyalahkan mereka.",
  ui_story_31150601_30_dialog_content = "Saya percaya bahwa mereka mungkin tidak sepenuhnya salah...",
  ui_story_31150601_31_dialog_content = "<color=#e8d9bb>Sebulan yang lalu...</color>",
  ui_story_31150601_32_dialog_content = "Itu saja untuk tugas-tugas terbaru kita.",
  ui_story_31150601_33_dialog_content = "Harap perhatikan waktu pengiriman yang ditentukan oleh pengirim.",
  ui_story_31150601_34_dialog_content = "Untuk surat yang mendesak, penting bagi kamu untuk memberi tahu pengirim tentang waktu tercepat yang mungkin.",
  ui_story_31150601_35_dialog_content = "Kirim dalam waktu yang disepakati. Tidak diperbolehkan perpanjangan.",
  ui_story_31150601_36_dialog_content = "Terkadang pengirim mungkin memiliki persyaratan khusus mengenai waktu pengantaran, jadi tolong perhatikan juga hal tersebut.",
  ui_story_31150601_37_dialog_content = "Jika kamu masih memiliki pertanyaan, kamu bisa datang ke serikat dan tanyakan kepada saya kapan saja.",
  ui_story_31150601_38_dialog_content = "Saya punya pertanyaan!",
  ui_story_31150601_39_dialog_content = "Lanjutkan.",
  ui_story_31150601_40_dialog_content = "Kami sudah di sini selama sebulan sekarang dan mendapatkan semua permintaan pengantaran ini setiap hari.",
  ui_story_31150601_41_dialog_content = "Apakah Courier Union hanya mampu menyediakan layanan pengantaran yang kuno seperti ini saja?!",
  ui_story_31150601_42_dialog_content = "Jika kita terus seperti ini, kita semua akan ditinggalkan pada akhirnya!",
  ui_story_31150601_43_dialog_content = "Dihentikan secara bertahap...? Maksudmu...",
  ui_story_31150601_44_dialog_content = "Ini berarti usang, dan tidak relevan lagi!",
  ui_story_31150601_45_dialog_content = "Banyak orang saat ini tidak lagi menggunakan Courier Union, kantor pos kecil pun juga dapat memenuhi kebutuhan mereka.",
  ui_story_31150601_46_dialog_content = "Benar. Terakhir kali saya mengantar pesanan, pelanggan bertanya apakah Courier Union menyediakan layanan pengiriman lainnya...",
  ui_story_31150601_47_dialog_content = "Ya! Aku sudah muak dengan ini selama sebulan terakhir! Cara kita mengirim barang rasanya seperti fosil tua. Itu tidak cocok di dunia modern!",
  ui_story_31150601_48_dialog_content = "Dan Pepi mengatakan sudah cukup sulit hanya untuk mengirimkan surat-surat itu.",
  ui_story_31150601_49_dialog_content = "Benar sekali!",
  ui_story_31150601_50_dialog_content = "Karena setiap orang di Courier Union memiliki pemikiran ini, serikat tersebut secara bertahap kehilangan relevansinya!",
  ui_story_31150601_51_dialog_content = "Tidak setuju, Lady Naroxel?",
  ui_story_31150601_52_dialog_content = "Akan kupertimbangkan semua yang kamu katakan dengan cermat.",
  ui_story_31150601_53_dialog_content = "Baik, lalu, selain dari tugas pengantaran saat ini, saya akan mengatur pekerjaan baru untuk semua orang—",
  ui_story_31150601_54_dialog_content = "Ketika kamu memiliki waktu, saya harap kalian semua dapat membantu mengumpulkan pendapat dari masyarakat.",
  ui_story_31150601_55_dialog_content = "Kompilasi pengalaman setiap orang dengan layanan Courier Union dan susunlah menjadi buku pendapat pengguna.",
  ui_story_31150601_56_dialog_content = "Saya rasa kita bisa mengakhiri hal-hal untuk hari ini.",
  ui_story_31150601_57_dialog_content = "Jadi itulah yang terjadi.",
  ui_story_31150601_58_dialog_content = "Hmm…",
  ui_story_31150601_59_dialog_content = "Apakah kamu juga berpikir... Aku ini fosil tua, yang tak punya tempat di dunia modern?",
  ui_story_31150601_60_option_content = "Kurasa kamu orang yang sibuk.",
  ui_story_31150601_61_dialog_content = "May Saya bertanya... apa maksud Anda dengan itu?",
  ui_story_31150601_62_dialog_content = "Nah, karena kamu selalu sibuk, kamu tidak punya waktu untuk melakukan hal lain selain mengirim surat.",
  ui_story_31150601_63_option_content = "Tentu saja tidak!",
  ui_story_31150601_64_dialog_content = "Ketika aku benar-benar memikirkannya, dengan mempertimbangkan semua yang aku tahu tentang kamu, aku yakin kamu adalah seseorang yang bersedia berubah seiring berjalannya waktu.",
  ui_story_31150601_65_dialog_content = "Dan \"fosil\" adalah seseorang yang keras kepala dan tidak mau berubah, kan?",
  ui_story_31150601_66_dialog_content = "Saya mengerti... Terima kasih.",
  ui_story_31150601_67_dialog_content = "Saya rasa saya butuh saran Anda.",
  ui_story_31150601_68_dialog_content = "Dalam pandangan Anda, mengirim surat pada dasarnya berarti mengirimnya tepat waktu, kan?",
  ui_story_31150601_69_dialog_content = "Itu dulu menjadi satu-satunya pertimbangan saat mengirim surat—",
  ui_story_31150601_70_dialog_content = "Tetapi kemungkinan baru telah terbuka.",
  ui_story_31150601_71_dialog_content = "Saya pikir pendatang baru itu di sana untuk mengingatkan kamu tentang hal ini.",
  ui_story_31150601_72_dialog_content = "Ya... Saya membaca pendapat pelanggan yang mereka kumpulkan dengan cermat setelah itu.",
  ui_story_31150601_73_dialog_content = "Tak pernah terpikir bahwa publik memiliki begitu banyak pendapat tentang serikat sebelum itu.",
  ui_story_31150601_74_dialog_content = "Hanya karena kamu begitu tenggelam dalam pekerjaanmu sehingga kamu mengabaikan kemungkinan pengembangan di masa depan.",
  ui_story_31150601_75_dialog_content = "Masuk akal juga…",
  ui_story_31150601_76_dialog_content = "Saya harus mundur selangkah sesekali, seperti yang Wendy katakan...",
  ui_story_31150601_77_dialog_content = "Tiba-tiba saya teringat masa kecil saya di Northland.",
  ui_story_31150601_78_dialog_content = "Dermaga bertiang di musim panas... sangat berbeda dengan pemandangan di sana.",
  ui_story_31150601_79_dialog_content = "Aku sibuk bolak-balik, sibuk dengan pekerjaan selama ini, bahkan belum sempat meluangkan waktu untuk menikmati langit biru di atas sana.",
  ui_story_31150601_80_dialog_content = "Senang akhirnya kamu menyadari itu!",
  ui_story_31150601_81_dialog_content = "Karena kita semua sedang liburan, jangan bicarakan pekerjaan lagi. Mari kita nikmati kesenangan berada di tepi pantai!",
  ui_story_31150601_82_dialog_content = "Bagaimana kalau kita pergi bermain di air?",
  ui_story_31150601_83_dialog_content = "Tentu saja…",
  ui_story_31150601_84_dialog_content = "Um... airnya agak dingin.",
  ui_story_31150601_85_dialog_content = "Nah, saya rasa semakin panas cuacanya, semakin dingin rasanya laut.",
  ui_story_31150601_86_dialog_content = "Sensasi mengapung di air sangat menenangkan.",
  ui_story_31150601_87_dialog_content = "Hah? Apa ini?",
  ui_story_31150601_88_dialog_content = "Apakah itu botol?",
  ui_story_31150601_89_dialog_content = "Sepertinya ada pesan yang digulung di dalamnya.",
  ui_story_31150601_90_dialog_content = "Buka itu!",
  ui_story_31150601_91_dialog_content = "Haruskah saya?",
  ui_story_31150601_92_dialog_content = "Tentu saja! Ini adalah surat tanpa kurir! Itu berarti siapa saja bisa membacanya!",
  ui_story_31150601_93_dialog_content = "Coba kulihat!",
  ui_story_31150601_94_dialog_content = "\"Indah indah laut, tolong penuhi keinginan ulang tahun saya.\"",
  ui_story_31150601_95_dialog_content = "\"Semoga Mama dan Papa selalu bersama selamanya dan merayakan ulang tahunku setiap tahun.\"",
  ui_story_31150601_96_dialog_content = "\"Jika segalanya bisa tetap seperti sekarang ini... Aku akan sangat bahagia, sekarang dan selamanya.\"",
  ui_story_31150601_97_dialog_content = "\"Sayang sekali laut, jika mungkin, aku juga ingin menjadi superstar saat aku tumbuh nanti...\"",
  ui_story_31150601_98_dialog_content = "Pfffff—",
  ui_story_31150601_99_dialog_content = "Gadis kecil ini sangat imut.",
  ui_story_31150601_100_dialog_content = "Dia menulis begitu banyak keinginan. Saya ingin tahu apakah ada yang akan menjadi kenyataan.",
  ui_story_31150601_101_dialog_content = "Heheh, aku akan mendoakan dia.",
  ui_story_31150601_102_dialog_content = "Benar. Ombak menjadi kurir surat ini...",
  ui_story_31150601_103_dialog_content = "Botol ini tidak memiliki penerima, karena hanya mewakili keinginan seseorang.",
  ui_story_31150601_104_dialog_content = "Aku paham sekarang...",
  ui_story_31150601_105_dialog_content = "Serikat Kurir dapat menyediakan lebih banyak layanan sesuai dengan kebutuhan masyarakat—",
  ui_story_31150601_106_dialog_content = "Seperti pesan dalam botol.",
  ui_story_31150601_107_dialog_content = "Beberapa metode pengiriman surat ada hanya untuk kesenangan semata.",
  ui_story_31150601_108_dialog_content = "Courier Union dapat menyediakan layanan pesan-dalam-botol tanpa penerima tetap untuk orang yang jauh dari laut. Ini mungkin menjadi hit.",
  ui_story_31150601_109_dialog_content = "Hmm, dan jika kita memperluas pemikiran kita lebih jauh lagi...",
  ui_story_31150601_110_dialog_content = "Kami juga dapat menyediakan layanan pengiriman pesan terjadwal, seperti layanan di mana Anda dapat mengirim pesan kepada diri Anda di masa depan.",
  ui_story_31150601_111_dialog_content = "Oh! Ini adalah jenis ide yang hanya bisa muncul dari pikiran kurir berpengalaman! Sungguh menarik!",
  ui_story_31150601_112_dialog_content = "Mengantarkan surat pada waktu yang berbeda akan memberikan pengalaman yang berbeda.",
  ui_story_31150601_113_dialog_content = "Saya rasa kita mungkin juga bisa mengadakan kegiatan mencocokkan teman pena anonim—",
  ui_story_31150601_114_dialog_content = "Even orang yang tidak memiliki surat untuk dikirim masih dapat menemukan alasan untuk berkomunikasi dengan orang lain melalui jenis aktivitas ini.",
  ui_story_31150601_115_dialog_content = "Bergantung pada takdir saja untuk menyatukan orang asing yang sama sekali tidak saling kenal. Ide yang sangat indah!",
  ui_story_31150601_116_dialog_content = "Kamu telah memberiku banyak ide yang menarik, PlayerName.",
  ui_story_31150601_117_dialog_content = "Saya ingin berterima kasih... karena telah membuka wawasan saya.",
  ui_story_31150601_118_dialog_content = "Segera setelah saya pulang, saya akan memberi tahu setiap orang tentang pengaturan kerja baru.",
  ui_story_31150601_119_dialog_content = "Dan sekarang, saya bisa menikmati sisa liburan saya tanpa beban di dunia ini!",
  ui_story_31150601_120_dialog_content = "Nah, mungkin bukan...",
  ui_story_31150601_121_dialog_content = "Hmm?",
  ui_story_31150601_122_dialog_content = "<color=#e8d9bb>Sebuah kabur bulu berwarna-warni melayang turun ke permukaan laut, saat Olive, kepala burung kukuk roh terjebak dalam botol yang mengapung di atas ombak.</color>",
  ui_story_31150601_123_dialog_content = "<size=45>Olive!!!</size>",
  ui_story_31150601_124_dialog_content = "Mengomel!",
  ui_story_31150601_125_dialog_content = "Kamu burung kecil yang penasaran... Bisakah kamu mengerti apa yang tertulis di lembar kertas itu?",
  ui_story_31150601_126_dialog_content = "Mengomel—!!! Mengomel!!!",
  ui_story_31150601_127_dialog_content = "Tunggu, biar aku membantu kamu..."
}
return config
